{
  "title": "The Glass Diver's Escape",
  "gate_token": "GYvMIAx_I8L1wvGfGG9U5g",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a map of the ruined city.",
      "visual_description": "Mara stands under a cracked archway, unrolling a parchment map in dim light.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver arrives through a shattered window.",
      "visual_description": "A figure in a clear diving helmet steps through a broken stained-glass window, glass shards tinkling.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning from a niche.",
      "visual_description": "An oil lamp with a single glowing eye in its flame sits in a wall niche, light casting shadows.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scampers ahead through rubble.",
      "visual_description": "A small clockwork fox with a key-wind tail and blue glass eyes darts over fallen stones.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The group enters the castle gates, now rusted and broken.",
      "visual_description": "Massive iron gates, rusted and hanging askew, frame the ruined courtyard beyond.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower looms ahead, its top wreathed in unnatural fog.",
      "visual_description": "A leaning stone tower with a single glowing window, mist swirling around its spire.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The Sleeping Tax Collector naps on a pile of ledgers.",
      "visual_description": "A figure in dusty robes dozes face-down on a stack of stamped papers and ledgers.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The Glass Diver peers into a mirror pool for a sign.",
      "visual_description": "The diver kneels beside a cracked mirror lying in a puddle, reflection rippling.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara checks her compass as the Tin Fox signals.",
      "visual_description": "Mara holds up a brass compass, the tin fox standing on hind legs pointing with a paw.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The Oracle Lamp warns of a trap behind a magic door.",
      "visual_description": "The lamp's flame flares, illuminating a door covered in glowing runes.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The Sleeping Tax Collector stirs but gives useless advice.",
      "visual_description": "He mumbles in his sleep, pointing vaguely at a wall, a stamp stuck to his sleeve.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "An armored patrol clanks through a distant street.",
      "visual_description": "Figures in dull plate armor march in the background, torches flickering.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The group hides behind old royal banners as the patrol passes.",
      "visual_description": "Tattered banners with faded crests flutter, the group pressed flat behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "A magic door swings open revealing a shortcut.",
      "visual_description": "The door creaks open, showing a corridor of swirling blue light.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The Tin Fox leads the way through the shortcut.",
      "visual_description": "The metal fox runs ahead, its tail winding, echoing in the magical passage.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The Sleeping Tax Collector is left behind, still snoring.",
      "visual_description": "He sleeps against a pillar, ledgers around him as the group moves on.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group reaches the escape bridge under moonlight.",
      "visual_description": "A narrow stone bridge spans a chasm, moonlit and creaking.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The Glass Diver leads the final crossing to safety.",
      "visual_description": "The diver steps onto the bridge, coat reflecting city lights, others following single file.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    }
  ]
}

